function icon(string $name, string $class = ''): string
{
    return '<svg class="icon ' . $class . '" viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">' . (ICONS[$name] ?? '') . '</svg>';
}

// labborrow mark: a flask inside a return arrow, borrow and give back (aky, 2026-11-24)
function logo_mark(string $class = ''): string
{
    return '<svg class="logo-mark ' . $class . '" viewBox="0 0 32 32" aria-hidden="true" focusable="false">'
        . '<rect width="32" height="32" rx="8" class="logo-bg"/>'
        . '<g transform="translate(4 4)" fill="none" class="logo-line" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'
        . '<path d="M21 12a9 9 0 1 1-2.6-6.4"/><path d="M15.4 5.5l3 .1.1-3"/><path d="M9.6 6.8h4.8"/>'
        . '<path d="M10.6 6.8v3.1l-2.8 5.2a1.3 1.3 0 0 0 1.15 1.9h6.1a1.3 1.3 0 0 0 1.15-1.9l-2.8-5.2V6.8"/><path d="M8.7 13.6h6.6"/>'
        . '</g></svg>';
}
